// Approved J24/J25/J26 DOM hierarchy, populated only with canonical scoped facts.
export function definitionView(doc,device,style,s,esc){style.textContent=[...doc.querySelectorAll('style')].map(n=>n.textContent).join('\n');const screen=doc.querySelector('[data-test-device]').cloneNode(true);screen.classList.add('composed-screen');device.replaceChildren(screen);screen.querySelectorAll('a').forEach(a=>{a.removeAttribute('href');a.setAttribute('role','button');a.tabIndex=0;a.dataset.action=a.classList.contains('add-tab')?'expense-home':a.textContent.trim().endsWith('People')?'people-home':a.textContent.trim().endsWith('You')?'account-home':'group-home';});screen.querySelector('#back').dataset.action='back';const content=screen.querySelector('#content');content.dataset.testState=s.state||'';content.innerHTML=`<div><div class="eyebrow">${esc(s.eyebrow||'')}</div><h1 class="hero">${esc(s.title)}</h1><p class="lead">${esc(s.lead||'')}</p></div>${s.facts?.length?`<section class="card pad stack">${s.facts.map(([k,v])=>`<div class="row"><span>${esc(k)}</span><b>${esc(v)}</b></div>`).join('')}</section>`:''}${s.notice?`<div class="notice ${esc(s.tone||'')}"><span class="mark">${s.tone==='success'?'✓':'i'}</span><span>${esc(s.notice)}</span></div>`:''}${s.special||''}<div class="actions">${(s.actions||[]).map(a=>`<button class="btn ${esc(a.kind||'ghost')}" data-action="${esc(a.action)}" ${a.extra||''}>${esc(a.label)}</button>`).join('')}</div>`;if(s.header)screen.querySelector('.header-title span').textContent=s.header;return content;}
